contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Take a dummy uint parameter so the checker treats this as a property over inputs.
    // The function is payable to allow this test contract to receive Ether if needed.
    function run(uint dummy) public payable {
        require(true);

        // Observe before-values
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // Make the state-changing call as owner (this contract is the owner of fresh c)
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe after-values
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // General rule: if withdrawAll did not revert then it emptied contract balance and did not change depositsCount
        assert(reverted || (afterBal == 0 && afterCount == beforeCount));
    }

    // Allow receiving Ether when withdrawAll transfers out
    receive() external payable {}
}

